-- Avatar · Datenbank · 06_startdaten.sql
-- Erzeugt aus dem Java-Code mit com.dan.avatarstudio.DbStartdaten (ant db-startdaten), nicht von Hand ändern.
-- Jede Zeile ein MERGE: fehlt sie, wird sie angelegt; MITGELIEFERT wird auf den Stand des Packages gebracht;
-- EIGEN bleibt, wie es ist. Wiederholbar. Dieses Skript löscht nichts.
-- =====================================================================================================

INSERT INTO AV_SCHEMA (VERSION, APP_VERSION, TEXT) VALUES (1, 'Phase 14', 'Typen, Kataloge, Presets, AV_API, Metadaten');

-- AV_REGLER: 52 Zeilen
MERGE INTO AV_REGLER t USING (SELECT 'gender' NAME, 'KOERPER' GRUPPE, 'Geschlecht (0 weiblich … 1 männlich)' BEZEICHNUNG, 0 MIN_WERT, 1 MAX_WERT, 0.5 VORGABE, 'macro.<w|m>.*' MORPHZIEL, 1 REIHENFOLGE FROM DUAL) s ON (t.NAME = s.NAME) WHEN MATCHED THEN UPDATE SET t.GRUPPE = s.GRUPPE, t.BEZEICHNUNG = s.BEZEICHNUNG, t.MIN_WERT = s.MIN_WERT, t.MAX_WERT = s.MAX_WERT, t.VORGABE = s.VORGABE, t.MORPHZIEL = s.MORPHZIEL, t.REIHENFOLGE = s.REIHENFOLGE WHERE t.HERKUNFT = 'MITGELIEFERT' WHEN NOT MATCHED THEN INSERT (NAME, GRUPPE, BEZEICHNUNG, MIN_WERT, MAX_WERT, VORGABE, MORPHZIEL, REIHENFOLGE, HERKUNFT) VALUES (s.NAME, s.GRUPPE, s.BEZEICHNUNG, s.MIN_WERT, s.MAX_WERT, s.VORGABE, s.MORPHZIEL, s.REIHENFOLGE, 'MITGELIEFERT');
